ROOT = Path(__file__).resolve().parents[1]
checks = 0


class FixtureHandler(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path in ('/dashboard-fixture/pages','/dashboard-fixture/templates','/dashboard-fixture/history','/dashboard-fixture/components','/dashboard-fixture/routes','/dashboard-fixture/external-pages','/dashboard-fixture/external-components'):
            origin = f'http://127.0.0.1:{self.server.server_port}'
            rendered = subprocess.run(['php', str(ROOT / 'tests/dashboard_fixture.php'), self.path.rsplit('/',1)[-1]], env={**os.environ, 'EDITOR_TEST_ORIGIN': origin}, capture_output=True, check=True).stdout
            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.end_headers()
            self.wfile.write(rendered)
        elif self.path in ('/', '/empty', '/error', '/extensions', '/components', '/component-editor', '/connect-data'):
            origin = f'http://127.0.0.1:{self.server.server_port}'
            rendered = subprocess.run(
                ['php', str(ROOT / 'tests/editor_fixture.php'), self.path.strip('/') or 'loaded'],
                env={**os.environ, 'EDITOR_TEST_ORIGIN': origin}, capture_output=True, check=True,
            ).stdout
            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.send_header('Content-Length', str(len(rendered)))
            self.end_headers()
            self.wfile.write(rendered)
        else:
            super().do_GET()

    def log_message(self, *_):
        pass


class Page:
    def __init__(self, endpoint, url):
        request = urllib.request.Request(endpoint + '/json/new?about:blank', method='PUT')
        target = json.load(urllib.request.urlopen(request))
        self.socket = connect(target['webSocketDebuggerUrl'], max_size=8 * 1024 * 1024)
        self.sequence = 0
        self.exceptions = []
        self.command('Page.enable')
        self.command('Runtime.enable')
        self.command('Emulation.setDeviceMetricsOverride', width=1440, height=940, deviceScaleFactor=1, mobile=False)
        self.command('Page.navigate', url=url)

    def command(self, method, **params):
        self.sequence += 1
        sequence = self.sequence
        self.socket.send(json.dumps({'id': sequence, 'method': method, 'params': params}))
        while True:
            message = json.loads(self.socket.recv(timeout=15))
            if message.get('method') == 'Runtime.exceptionThrown':
                self.exceptions.append(message['params']['exceptionDetails'])
            if message.get('id') == sequence:
                if 'error' in message:
                    raise RuntimeError(message['error'])
                return message.get('result', {})

    def evaluate(self, expression):
        result = self.command('Runtime.evaluate', expression=expression, returnByValue=True, awaitPromise=True)
        if 'exceptionDetails' in result:
            raise RuntimeError(result['exceptionDetails'])
        return result.get('result', {}).get('value')

    def wait(self, expression):
        deadline = time.monotonic() + 10
        while time.monotonic() < deadline:
            if self.evaluate(expression):
                return
            time.sleep(0.05)
        raise AssertionError(f'Timed out waiting for {expression}; exceptions: {self.exceptions}')

    def check(self, expression, message):
        global checks
        if not self.evaluate(expression):
            raise AssertionError(message)
        checks += 1


