def exercise_plain_language(endpoint, origin, screenshot=None):
    page = Page(endpoint, origin + '/')
    page.wait('!!window.QuillEditor && !!document.querySelector("iframe").contentDocument.querySelector("h1")')
    page.evaluate('QuillEditor.select("0.0")')
    page.wait('!!document.querySelector("[data-style=opacity]")')
    page.evaluate('document.querySelector("#editor-tab-style").click()')
    page.check('document.querySelector("#editor-tab-display").textContent === "Position" && document.querySelector("#editor-tab-style").textContent === "Appearance"', 'Property navigation describes user goals')
    page.evaluate('var opacity=document.querySelector("[data-style=opacity]");opacity.value="35";opacity.dispatchEvent(new Event("input"))')
    page.wait('QuillEditor.getStyleDeclarations().opacity === "0.35"')
    page.check('document.querySelector("[data-style=opacity]").value === "35" && getComputedStyle(QuillEditor.canvas.getElement("0.0")).opacity === "0.35"', 'Opacity percentage updates the rendered appearance')
    page.evaluate('document.querySelector("[data-reset-style=opacity]").click();QuillEditor.setStyle("display","grid");document.querySelector("#editor-tab-layout").click()')
    page.wait('!!document.querySelector("[data-track-count=grid-template-columns]")')
    page.evaluate('var columns=document.querySelector("[data-track-count=grid-template-columns]");columns.value="3";columns.dispatchEvent(new Event("input"))')
    page.wait('QuillEditor.getStyleDeclarations().gridTemplateColumns === "repeat(3, minmax(0px, 1fr))" || QuillEditor.getStyleDeclarations().gridTemplateColumns === "repeat(3, minmax(0, 1fr))"')
    page.check('getComputedStyle(QuillEditor.canvas.getElement("0.0")).gridTemplateColumns.split(" ").length === 3', 'Column count creates three equal rendered columns')
    page.evaluate('QuillEditor.setStyle("grid-template-columns","120px 2fr 1fr")')
    page.check('document.querySelector("[data-style=grid-template-columns]").value === "120px 2fr 1fr" && document.querySelector("[data-track-count=grid-template-columns]").value === "3"', 'Custom column widths remain available without replacing existing values')
    page.check('[...document.querySelector("[data-style=position]").options].find(option=>option.value === "sticky").text === "Stay in view" && [...document.querySelector("[data-style=font-weight]").options].find(option=>option.value === "600").text === "Semibold"', 'Placement and font choices use familiar descriptions')
    page.evaluate('document.querySelector("#editor-tab-style").click();document.querySelector("[data-style=background-color]").closest("details").open=true')
    page.check('getComputedStyle(document.querySelector("[data-style=background-color]")).borderTopWidth === "0px" && getComputedStyle(document.querySelector("[data-gradient-for=background-color]")).borderTopWidth === "0px"', 'Color swatches and paint actions have no frames')
    page.check('getComputedStyle(document.querySelector("[data-style=background-color]")).width === "32px"', 'Clean swatches retain their usable target size')
    page.evaluate('QuillEditor.setAttribute("class", null);QuillEditor.setStyle("background-color", "");QuillEditor.setStyle("background-image", "none")')
    page.wait('document.querySelector("[data-style=background-color]").value === "#ffffff"')
    page.check('document.querySelector("[data-style=background-color]").value === "#ffffff" && !QuillEditor.getStyleDeclarations().backgroundColor', 'Unset transparent backgrounds seed an opaque white picker without changing the document')
    page.evaluate('QuillEditor.setStyle("background-color", "transparent")')
    page.check('document.querySelector("[data-style=background-color]").value === "transparent"', 'Explicit transparent color choices remain editable')
    page.evaluate('QuillEditor.setStyle("background-color", "#123456")')
    page.wait('document.querySelector("[data-style=background-color]").value === "rgb(18, 52, 86)"')
    page.check('document.querySelector("[data-style=background-color]").value === QuillEditor.getStyleDeclarations().backgroundColor', 'Existing colors retain their value')

    if screenshot:
        Path(screenshot).with_name('quill-clean-colors.png').write_bytes(base64.b64decode(page.command('Page.captureScreenshot', format='png')['data']))
    if page.exceptions:
        raise AssertionError(page.exceptions)


def exercise_link_destinations(endpoint, origin, screenshot=None):
    page = Page(endpoint, origin + '/')
    page.wait('!!window.QuillEditor && !!document.querySelector("iframe").contentDocument.querySelector("h1")')
    page.evaluate('QuillEditor.select("0.0.2")')
    page.wait('!!document.querySelector("[data-link-field=type]")')
    page.evaluate('document.querySelector("#editor-tab-link").click();window.linkField=(key,value)=>{const input=document.querySelector(`[data-link-field="${key}"]`);input.value=value;input.dispatchEvent(new Event(input.tagName==="SELECT"&&["type","route"].includes(key)?"change":"input",{bubbles:true}))}')
    page.check('QuillEditor.routes.some(route=>route.path==="/products/{slug}") && document.querySelector("[data-link-field=route]").options.length===4', 'Link destinations receive registered framework routes')
    page.evaluate('linkField("type","route");linkField("route","/contact")')
    page.wait('QuillEditor.getSelectedBlock().attributes.href === "/contact"')
    page.check('document.querySelector(`[aria-label="Link destination"]`).value==="/contact"', 'A static site route writes its path to the real link')
    page.evaluate('linkField("route","/products/{slug}")')
    page.check('!QuillEditor.getSelectedBlock().attributes.href && !!document.querySelector("[data-route-parameter=slug]")', 'Parameterized routes ask for values without storing unresolved placeholders')
    page.evaluate('linkField("route-slug","Čaj & kafa")')
    page.wait('QuillEditor.getSelectedBlock().attributes.href === "/products/%C4%8Caj%20%26%20kafa"')
    page.check('QuillEditor.canvas.getElement("0.0.2").getAttribute("href")==="/products/%C4%8Caj%20%26%20kafa"', 'Route values are encoded as a single path segment')
    page.evaluate('QuillEditor.setAttribute("href","/products/test?sort=price#reviews")')
    page.wait('document.querySelector("[data-link-field=route-slug]").value === "test"')
    page.evaluate('linkField("route-slug","new product")')
    page.check('QuillEditor.getSelectedBlock().attributes.href==="/products/new%20product?sort=price#reviews"', 'Editing a route preserves existing query and fragment')
    page.evaluate('linkField("type","email");linkField("email","hello@example.com");linkField("subject","Čaj & kafa");linkField("body","Hello\\nSee you!")')
    page.wait('QuillEditor.getSelectedBlock().attributes.href === "mailto:hello@example.com?subject=%C4%8Caj%20%26%20kafa&body=Hello%0ASee%20you!"')
    page.check('document.querySelector("[data-link-field=target]").closest("details").hidden', 'Email destinations open an email app instead of showing browser frame settings')
    page.evaluate('QuillEditor.setAttribute("href","mailto:hello@example.com?cc=team%40example.com&subject=Old");')
    page.wait('document.querySelector("[data-link-field=subject]").value === "Old"')
    page.evaluate('linkField("subject","New")')
    page.check('QuillEditor.getSelectedBlock().attributes.href.includes("cc=team%40example.com") && QuillEditor.getSelectedBlock().attributes.href.includes("subject=New")', 'Editing an existing email preserves additional recipients')
    page.evaluate('linkField("type","phone");linkField("phone","+381 (64) 123-4567")')
    page.check('QuillEditor.getSelectedBlock().attributes.href==="tel:+381641234567"', 'Phone links normalize visual spacing')
    page.evaluate('linkField("type","sms");linkField("sms","+381 64 1234567")')
    page.check('QuillEditor.getSelectedBlock().attributes.href==="sms:+381641234567"', 'Text message links use the messaging scheme')
    page.evaluate('linkField("type","calendar");linkField("calendar","https://example.com/events.ics")')
    page.check('QuillEditor.getSelectedBlock().attributes.href==="webcal://example.com/events.ics"', 'Calendar subscriptions use the calendar app scheme')
    page.evaluate('linkField("calendar-mode","file")')
