def exercise_resize(endpoint, origin, screenshot=None):
    page = Page(endpoint, origin + '/')
    page.wait('!!window.QuillEditor && !!QuillEditor.canvas.getElement("0.0")')
    page.evaluate('QuillEditor.select("0.0");QuillEditor.setStyleDeclarations("width:300px;height:160px;padding:20px;border:4px solid black;box-sizing:border-box");document.querySelector("#editor-zoom").value="1";document.querySelector("#editor-zoom").dispatchEvent(new Event("change"))')
    page.wait('document.querySelector("#editor-canvas-stage").dataset.scale === "1" && !!document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=se]")')
    page.check('document.querySelector("iframe").contentDocument.querySelectorAll("[data-quill-resize]").length === 3 && !JSON.stringify(QuillEditor.getDocument()).includes("quill-resize")', 'Right, bottom and bottom-right resize handles are editor-only overlays')

    def start(direction):
        page.evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')
        point = page.evaluate('''(() => {const frame=document.querySelector("iframe"),b=frame.getBoundingClientRect(),h=frame.contentDocument.querySelector('[data-quill-resize="DIRECTION"]').getBoundingClientRect(),scale=QuillEditor.ui.viewport.getViewport().scale;return {x:b.left+(h.left+h.width/2)*scale,y:b.top+(h.top+h.height/2)*scale}})()'''.replace('DIRECTION', direction))
        page.command('Input.dispatchMouseEvent', type='mouseMoved', **point)
        page.command('Input.dispatchMouseEvent', type='mousePressed', button='left', buttons=1, clickCount=1, **point)
        return point

    def move(point, dx, dy, modifiers=0):
        target = dict(x=point['x'] + dx, y=point['y'] + dy)
        page.command('Input.dispatchMouseEvent', type='mouseMoved', button='left', buttons=1, modifiers=modifiers, **target)
        return target

    def release(point, modifiers=0):
        page.command('Input.dispatchMouseEvent', type='mouseReleased', button='left', buttons=0, clickCount=1, modifiers=modifiers, **point)

    page.evaluate('window.resizeBefore=JSON.stringify(QuillEditor.getDocument());window.resizeRevision=QuillEditor.state.revision')
    point = start('se'); release(point)
    page.check('QuillEditor.state.revision===resizeRevision && QuillEditor.selectedPath==="0.0"', 'Clicking a resize handle without dragging leaves dimensions and selection unchanged')
    point = start('se'); target = move(point, 60, 40)
    page.check('Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().width-360)<1 && Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().height-200)<1 && QuillEditor.state.revision===resizeRevision', 'Pointer drag previews dimensions without adding history entries')
    release(target)
    page.wait('QuillEditor.state.revision===resizeRevision+1')
    page.check('QuillEditor.getStyleDeclarations().width==="360px" && QuillEditor.getStyleDeclarations().height==="200px"', 'Corner resize commits both border-box dimensions together')
    page.evaluate('QuillEditor.ui.history.undo()')
    page.wait('JSON.stringify(QuillEditor.getDocument())===resizeBefore')
    page.check('QuillEditor.getStyleDeclarations().width==="300px" && QuillEditor.getStyleDeclarations().height==="160px"', 'One Undo restores the entire resize gesture')
    point = start('e'); target = move(point, 40, 0)
    page.command('Input.dispatchKeyEvent', type='keyDown', key='Escape', code='Escape', windowsVirtualKeyCode=27)
    release(target)
    page.check('JSON.stringify(QuillEditor.getDocument())===resizeBefore && Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().width-300)<1', 'Escape restores the original preview and leaves saved dimensions untouched')
    point = start('se'); target = move(point, 60, 3, 8); release(target, 8)
    page.wait('QuillEditor.getStyleDeclarations().width==="360px"')
    page.check('QuillEditor.getStyleDeclarations().height==="192px"', 'Shift preserves the block aspect ratio')
    page.evaluate('QuillEditor.setStyle("box-sizing","content-box");QuillEditor.setStyleDeclarations("width:240px;height:120px;padding:20px;border:4px solid black;box-sizing:content-box")')
    page.wait('Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().width-288)<1')
    point = start('e'); target = move(point, 30, 0); release(target)
    page.wait('QuillEditor.getStyleDeclarations().width==="270px"')
    page.check('QuillEditor.getStyleDeclarations().height==="120px" && Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().width-318)<1', 'Edge resize respects content-box padding and borders and leaves the other axis unchanged')
    page.evaluate('document.querySelector("#editor-viewport").value="390";document.querySelector("#editor-viewport").dispatchEvent(new Event("change"));document.querySelector("#editor-zoom").value="0.5";document.querySelector("#editor-zoom").dispatchEvent(new Event("change"));QuillEditor.setStyleViewport("mobile")')
    page.wait('QuillEditor.ui.viewport.getViewport().scale===0.5 && document.querySelector("iframe").contentWindow.innerWidth===390 && document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=e]").getBoundingClientRect().width===36')
    point = start('e'); target = move(point, 15, 0); release(target)
    page.wait('QuillEditor.getBlock("0.0").styles.mobile.width==="300px"')
    page.check('QuillEditor.getBlock("0.0").styles.base.width==="270px" && Math.abs(document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=e]").getBoundingClientRect().width*0.5-18)<1', 'Zoomed resizing uses logical pixels, writes only the selected viewport and keeps handles usable')
    if screenshot:
        Path(screenshot).with_suffix('.resize.png').write_bytes(base64.b64decode(page.command('Page.captureScreenshot', format='png')['data']))
    page.evaluate('QuillEditor.setStyleViewport("all");QuillEditor.select("0.0.2");window.resizeInlineWidth=QuillEditor.canvas.getElement("0.0.2").getBoundingClientRect().width;window.resizeInlineBefore=JSON.stringify(QuillEditor.getDocument())')
    point = start('e'); target = move(point, 10, 0); release(target)
    page.wait('QuillEditor.getStyleDeclarations().display==="inline-block"')
    page.check('Math.abs(parseFloat(QuillEditor.getStyleDeclarations().width)-resizeInlineWidth-20)<0.2 && getComputedStyle(QuillEditor.canvas.getElement("0.0.2")).display==="inline-block"', 'Pointer resize retains the display adjustment for inline blocks when committing the preview')
    page.evaluate('QuillEditor.ui.history.undo()')
    page.wait('JSON.stringify(QuillEditor.getDocument())===resizeInlineBefore')
    page.evaluate('document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=e]").focus()')
    page.command('Input.dispatchKeyEvent', type='keyDown', key='ArrowRight', code='ArrowRight', modifiers=8, windowsVirtualKeyCode=39)
    page.wait('QuillEditor.getStyleDeclarations().display==="inline-block"')
    page.check('Math.abs(parseFloat(QuillEditor.getStyleDeclarations().width)-resizeInlineWidth-10)<0.2', 'Keyboard resize applies dimensions to inline elements by making them inline-block')
    page.wait('document.querySelector("iframe").contentDocument.activeElement?.dataset.quillResize==="e"')
    page.check('document.querySelector("iframe").contentDocument.activeElement.dataset.quillResize==="e"', 'Keyboard resize preserves handle focus after rendering')
    page.evaluate('QuillEditor.select("0.0");QuillEditor.setStyleViewport("mobile");QuillEditor.setStyleDeclarations("width:300px;height:160px;min-width:300px;max-width:300px;box-sizing:border-box")')
    page.wait('document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=e]").hidden')
    page.check('document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=se]").hidden && !document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=s]").hidden', 'Fixed width hides the right and corner handles while leaving height resizable')
    point = start('s'); target = move(point, 0, 10, 8); release(target, 8)
    page.wait('QuillEditor.getStyleDeclarations().height==="180px"')
    page.check('QuillEditor.getStyleDeclarations().width==="300px"', 'Shift on the remaining handle preserves the constrained axis')
    page.evaluate('QuillEditor.setStyleDeclarations("width:300px;height:160px;min-height:160px;max-height:160px;box-sizing:border-box")')
    page.wait('document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=s]").hidden')
    page.check('document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=se]").hidden && !document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=e]").hidden', 'Fixed height leaves only the right resize handle')
    page.evaluate('QuillEditor.setStyleDeclarations("width:300px;height:160px;min-width:280px;max-width:320px;box-sizing:border-box")')
    page.wait('!document.querySelector("iframe").contentDocument.querySelector("[data-quill-resize=e]").hidden')
    point = start('e'); target = move(point, 40, 0); release(target)
    page.wait('QuillEditor.getStyleDeclarations().width==="320px"')
    page.check('Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().width-320)<1', 'Resize values stop at the block maximum width')
    point = start('e'); target = move(point, -40, 0); release(target)
    page.wait('QuillEditor.getStyleDeclarations().width==="280px"')
    page.check('Math.abs(QuillEditor.canvas.getElement("0.0").getBoundingClientRect().width-280)<1', 'Resize values stop at the block minimum width')
    anchor_cases = [
        ('absolute', 'left:auto;right:20px;top:100px;bottom:auto', ['w', 's', 'sw'], 'w', -10, 0, 220, 120),
        ('absolute', 'left:20px;right:auto;top:auto;bottom:100px', ['e', 'n', 'ne'], 'n', 0, -10, 200, 140),
        ('fixed', 'left:auto;right:20px;top:auto;bottom:100px', ['w', 'n', 'nw'], 'nw', -10, -10, 220, 140),
        ('fixed', 'left:20px;right:auto;top:100px;bottom:auto', ['e', 's', 'se'], 'se', 10, 10, 220, 140),
        ('relative', 'left:auto;right:20px;top:auto;bottom:20px', ['e', 's', 'se'], 'e', 10, 0, 220, 120),
        ('absolute', 'direction:rtl;left:20px;right:20px;top:100px;bottom:auto', ['e', 's', 'se'], 'e', 10, 0, 220, 120),
    ]
    for position, insets, handles, direction, dx, dy, width, height in anchor_cases:
        css = f'position:{position};{insets};width:200px;height:120px;padding:0;border:0;box-sizing:border-box'
