    page.check('motionTarget.hidden && motionTarget.getAnimations().length===0', 'Reduced motion also skips the exit animation')
    page.command('Emulation.setEmulatedMedia', features=[])
    page.evaluate('stopMotion();motionAction.steps[0].operation.animation={effect:"fade",duration:200,easing:"linear"};window.stopMotion=QuillActions.mount(motionRoot,{actions:[motionAction]});motionButton.click();window.fadeMotion=motionTarget.getAnimations()[0]')
    page.check('fadeMotion.effect.getKeyframes()[0].transform===fadeMotion.effect.getKeyframes()[1].transform && fadeMotion.effect.getKeyframes()[0].opacity==="0"', 'Fade changes opacity while preserving the authored transform')
