    page.wait('motionTarget.getAnimations().length===0')
    page.evaluate('stopMotion();motionAction.steps[0].operation.animation.duration=0;window.stopMotion=QuillActions.mount(motionRoot,{actions:[motionAction]});motionButton.click()')
    page.check('motionTarget.hidden && motionTarget.getAnimations().length===0', 'A zero duration animation switches visibility immediately')
