    page.check('QuillEditor.getBlock("0.1").descriptor.name === "p" && QuillEditor.getBlock("0.0").children.length === 2', 'Tree drag can extract a child through the main drop zone')
    page.wait('!!QuillEditor.canvas.getElement("0.0.0")')
