    page.check('QuillEditor.getBlock("0.2").descriptor.name === "h1" && QuillEditor.getBlock("0.0").children.length === 1', 'Outer workspace background accepts canvas drags onto main')
    page.evaluate('window.dragData=new DataTransfer();document.querySelector(`[data-path="0.0.0"]`).closest(".editor-tree-row").dispatchEvent(new DragEvent("dragstart",{bubbles:true,dataTransfer:dragData}));var target=document.querySelector(`[data-section="0"] > summary`);target.dispatchEvent(new DragEvent("dragover",{bubbles:true,dataTransfer:dragData}));target.dispatchEvent(new DragEvent("drop",{bubbles:true,dataTransfer:dragData}))')
    page.check('QuillEditor.getBlock("0.3").descriptor.name === "a" && QuillEditor.getBlock("0.0").children.length === 0', 'Main section heading accepts a nested block outside its parent')
    page.evaluate('var doc=QuillEditor.getDocument();doc.sections=[doc.sections[1],{name:"main",blocks:[]}];QuillEditor.state.restoreDocument(doc,null)')
    page.wait('QuillEditor.canvas.getElement("0.0")?.textContent === "Made with Quill" && !QuillEditor.canvas.getElement("0.1")')
    page.evaluate('window.dragData=new DataTransfer();QuillEditor.canvas.getElement("0.0").dispatchEvent(new DragEvent("dragstart",{bubbles:true,dataTransfer:dragData}));document.querySelector("iframe").contentDocument.documentElement.dispatchEvent(new DragEvent("dragover",{bubbles:true,dataTransfer:dragData}));document.querySelector("iframe").contentDocument.documentElement.dispatchEvent(new DragEvent("drop",{bubbles:true,dataTransfer:dragData}))')
    page.check('QuillEditor.getDocument().sections[0].blocks.length === 0 && QuillEditor.getBlock("1.0").content === "Made with Quill"', 'Blank canvas resolves an empty main section by name rather than assuming the first section')
    page.wait('!!QuillEditor.canvas.getElement("1.0")')
    page.evaluate('window.dragData=new DataTransfer();QuillEditor.canvas.getElement("1.0").dispatchEvent(new DragEvent("dragstart",{bubbles:true,dataTransfer:dragData}));document.querySelector("iframe").contentDocument.dispatchEvent(new DragEvent("dragend",{bubbles:true,dataTransfer:dragData}))')
    page.check('document.querySelector("#editor-main-drop").hidden && !JSON.stringify(QuillEditor.getDocument()).includes("data-quill-main-drop")', 'Cancelled drag clears the indicator without adding editor UI to the document')
