def exercise_viewports(endpoint, origin):
    page = Page(endpoint, origin + '/')
    page.wait('!!window.QuillEditor && !!document.querySelector("iframe").contentDocument.querySelector("h1") && document.querySelector("iframe").contentWindow.innerWidth === 1440')
    page.evaluate('window.beforeViewport=JSON.stringify(QuillEditor.getDocument());window.originalHeading=document.querySelector("iframe").contentDocument.querySelector("h1");var style=document.createElement("style");style.textContent=".hero{--preview-device:desktop}@media(max-width:1000px){.hero{--preview-device:tablet}}@media(max-width:500px){.hero{--preview-device:mobile}}";document.querySelector("iframe").contentDocument.head.append(style)')
    page.check('getComputedStyle(document.querySelector("iframe").contentDocument.querySelector(".hero")).getPropertyValue("--preview-device")==="desktop"', 'Desktop uses a real 1440px viewport even with sidebars')
    page.check('document.querySelector(".editor-canvas-area").scrollWidth <= document.querySelector(".editor-canvas-area").clientWidth + 1', 'Fit desktop has no phantom horizontal overflow')
    for width, mode in [(768, 'tablet'), (390, 'mobile'), (1440, 'desktop')]:
        page.evaluate(f'document.querySelector("#editor-viewport").value="{width}";document.querySelector("#editor-viewport").dispatchEvent(new Event("change"))')
        page.wait(f'document.querySelector("iframe").contentWindow.innerWidth === {width}')
        page.check(f'getComputedStyle(document.querySelector("iframe").contentDocument.querySelector(".hero")).getPropertyValue("--preview-device")==="{mode}"', f'{mode.title()} mode triggers corresponding responsive CSS')
    page.evaluate('document.querySelector("#editor-zoom").value="0.5";document.querySelector("#editor-zoom").dispatchEvent(new Event("change"))')
    page.wait('document.querySelector("iframe").style.transform === "scale(0.5)"')
    page.check('document.querySelector("iframe").contentWindow.innerWidth === 1440 && getComputedStyle(document.querySelector("iframe").contentDocument.querySelector(".hero")).getPropertyValue("--preview-device")==="desktop"', 'Zoom scales desktop without changing responsive width')
    page.evaluate('document.querySelector("#editor-viewport").value="390";document.querySelector("#editor-viewport").dispatchEvent(new Event("change"))')
    page.wait('document.querySelector("iframe").contentWindow.innerWidth === 390')
    page.check('(() => {var area=document.querySelector(".editor-canvas-area").getBoundingClientRect();var stage=document.querySelector("#editor-canvas-stage").getBoundingClientRect();return Math.abs((stage.left+stage.right)-(area.left+area.right))<2 && Math.abs(stage.width-195)<1})()', 'Scaled mobile is centered and reserves only painted space')
    page.evaluate('document.querySelector("#editor-zoom").value="fit";document.querySelector("#editor-zoom").dispatchEvent(new Event("change"));document.querySelector("#editor-viewport").value="1440";document.querySelector("#editor-viewport").dispatchEvent(new Event("change"))')
    page.wait('document.querySelector("iframe").contentWindow.innerWidth === 1440')
    page.command('Emulation.setDeviceMetricsOverride', width=1100, height=780, deviceScaleFactor=1, mobile=False)
    page.wait('Math.abs(document.querySelector("#editor-canvas-stage").getBoundingClientRect().width-document.querySelector(".editor-canvas-area").clientWidth)<2')
    page.check('document.querySelector("iframe").contentWindow.innerWidth === 1440', 'Host window resize fits preview while retaining device viewport width')
    page.evaluate('document.querySelector("#editor-zoom").value="1";document.querySelector("#editor-zoom").dispatchEvent(new Event("change"))')
    page.wait('document.querySelector("#editor-canvas-stage").style.width === "1440px"')
    page.check('document.querySelector(".editor-canvas-area").scrollWidth >= 1440', 'Desktop at 100 percent can scroll across full viewport')
    page.evaluate('document.querySelector(".editor-canvas-area").scrollLeft=300;document.querySelector("#editor-viewport").value="390";document.querySelector("#editor-viewport").dispatchEvent(new Event("change"))')
    page.wait('document.querySelector("iframe").contentWindow.innerWidth === 390')
    page.check('document.querySelector(".editor-canvas-area").scrollLeft === 0 && document.querySelector(".editor-canvas-area").scrollWidth <= document.querySelector(".editor-canvas-area").clientWidth + 1', 'Returning to mobile clears horizontal scroll and phantom overflow')
    page.check('JSON.stringify(QuillEditor.getDocument()) === beforeViewport && !quillEditor.dirty && document.querySelector("iframe").contentDocument.querySelector("h1") === originalHeading', 'Device and zoom changes preserve document, dirty state and canvas nodes')
    page.check('!!document.querySelector(`label[for="editor-viewport"] .fa-mobile-screen-button`) && document.querySelector("#editor-viewport-size").textContent === "390px"', 'Viewport toolbar shows current device icon and logical width')
    if page.exceptions:
        raise AssertionError(page.exceptions)


