    page.check('document.querySelector(".editor-radius-preview").style.borderTopLeftRadius === "18px" && document.querySelector(".editor-radius-preview").style.borderBottomRightRadius === "28px" && document.querySelector("[data-radius-corner=bottom-right]").getAttribute("aria-pressed") === "true"', 'Corner preview follows independent radii and selection')
