    page.wait('!document.querySelector("[data-control=background-size]").hidden')
    page.check('document.querySelector("iframe").contentDocument.querySelector(".hero").style.backgroundImage.includes("Screenshot_20261016_003933.png")', 'Background URL updates the canvas immediately')
