    page.check('document.querySelector("#clr-picker").classList.contains("clr-pill") && !!document.querySelector("#clr-close i.fa-solid")', 'Coloris uses a horizontal gray picker with Font Awesome actions')
    if screenshot:
        Path(screenshot).with_suffix('.coloris.png').write_bytes(base64.b64decode(page.command('Page.captureScreenshot', format='png')['data']))
