    page.evaluate('QuillEditor.select(null);QuillEditor.insertBlock("Quill:ol",0,null);window.listPath=QuillEditor.selectedPath')
    page.wait('!!document.querySelector("[data-structure=list-items]") && !document.querySelector("#editor-tab-table")')
    page.evaluate('QuillEditor.setContent("Keep item",listPath+".0");QuillEditor.select(listPath);changeStructure("list-items",5);changeStructure("list-start",4);changeStructure("list-reversed",true)')
    page.check('QuillEditor.getSelectedBlock().children.length===5 && QuillEditor.getSelectedBlock().children[0].content==="Keep item" && QuillEditor.canvas.getElement(listPath).start===4 && QuillEditor.canvas.getElement(listPath).reversed', 'List settings resize native items and apply ordered numbering')
    page.evaluate('changeStructure("list-type","ul");changeStructure("list-items",2)')
    page.check('QuillEditor.getSelectedBlock().descriptor.name==="ul" && QuillEditor.getSelectedBlock().children.length===2 && !Object.hasOwn(QuillEditor.getSelectedBlock().attributes,"reversed") && !Object.hasOwn(QuillEditor.getSelectedBlock().attributes,"start")', 'Switching list type keeps items and clears ordered-only attributes')
