def exercise_visual_system(endpoint, origin, screenshot):
    """A combined document catches theme leakage and context/overlay regressions."""
    page = Page(endpoint, origin + '/')
    page.wait('!!window.QuillEditor && !!QuillEditor.canvas.getElement("0.0")')
    page.evaluate('''(() => {
        QuillEditor.select("0.0");
        QuillEditor.insertBlock("Quill:two-columns",0,"0.0");
        window.complexGrid=QuillEditor.selectedPath;
        QuillEditor.insertBlock("Quill:button",0,complexGrid+".0");
        window.complexButton=QuillEditor.selectedPath;
        QuillEditor.setStyle("background-image","linear-gradient(90deg, #136344, #3355aa)");
        QuillEditor.setStyle("transform","rotate(3deg)");
        QuillEditor.setStyle("transform-origin","100% 0%");
        QuillEditor.setStyle("transition","opacity 200ms ease");
        QuillEditor.setStyle("width","120px");
        QuillEditor.setStyleViewport("mobile");QuillEditor.setStyle("width","100px");
        QuillEditor.setStyleState("hover");QuillEditor.setStyle("opacity","0.7");
        QuillEditor.setStyleViewport("all");QuillEditor.setStyleState("default");
        QuillEditor.insertBlock("Quill:icon",0,complexGrid+".1");
        const shared={schema_version:1,sections:[{name:"main",blocks:[{descriptor:{name:"p",props:{},renderer:""},attributes:{},content:"Shared nested content",children:[]}]}]};
        const info={id:91,name:"Theme fixture",version:1};
        const nativeFetch=window.fetch;
        window.fetch=(url,options)=>String(url).endsWith('/91') ? Promise.resolve(new Response(JSON.stringify({data:{document:shared,component:info}}),{status:200})) : nativeFetch(url,options);
        QuillEditor.state.insertComponent(info,shared,0,complexGrid+".1");
        const action={id:"qa-theme",name:"Reveal",trigger:"click",steps:[{id:"qs-theme",target:{type:"self"},condition:{type:"visible"},operation:{type:"toggle-visibility",animation:{effect:"fade",duration:200}}}]};
        QuillEditor.state.updateActions([action],[{path:complexButton,editor:{onClick:action.id}}]);
        QuillEditor.select(complexButton);
        window.themeDocument=JSON.stringify(QuillEditor.getDocument());
        window.themeRevision=QuillEditor.state.revision;
    })()''')
    page.wait('!!document.querySelector("[data-control=width]") && !!document.querySelector("iframe").contentDocument.querySelector("[data-quill-toolbar]")')
    page.wait('document.querySelector("[data-control=width]").dataset.valueSource === "assigned"')
    page.check('document.querySelector("#editor-style-context").textContent.includes("Shared styles") && document.querySelector("#quill-editor").dataset.documentDirty==="true"', 'Inspector context and unsaved indicator reflect existing state')
    page.evaluate('QuillEditor.setStyleViewport("mobile");QuillEditor.setStyleState("hover")')
    page.wait('document.querySelector("[data-control=opacity]").dataset.valueSource === "override"')
    page.check('document.querySelector("#editor-style-context").textContent.includes("Mobile") && document.querySelector("#editor-style-context").textContent.includes("Hover") && document.querySelector("[data-control=height]").dataset.valueSource==="inherited"', 'Value markers distinguish active state/device assignments from inherited appearance')
    page.evaluate('QuillEditor.setStyleViewport("all");QuillEditor.setStyleState("default");document.querySelector("#editor-tab-layout").click()')
    page.evaluate('document.querySelectorAll("#editor-panel-layout details").forEach(section=>section.open=true)')
    for theme in ('light', 'dark'):
        page.command('Emulation.setEmulatedMedia', features=[{'name':'prefers-color-scheme','value':theme}])
        expected = '#f8f9fa' if theme == 'light' else '#242628'
        page.wait('getComputedStyle(document.documentElement).getPropertyValue("--editor-bg").trim()==='+json.dumps(expected))
        page.wait('getComputedStyle(document.querySelector("iframe").contentDocument.documentElement).getPropertyValue("--editor-bg").trim()==='+json.dumps(expected))
        page.check('''(() => {const d=document.querySelector('iframe').contentDocument,t=d.querySelector('[data-quill-toolbar]');const probe=document.createElement('span');probe.style.background='var(--editor-bg)';document.body.append(probe);const matches=getComputedStyle(t).backgroundColor===getComputedStyle(probe).backgroundColor;probe.remove();return matches && QuillEditor.getSelectedBlock().styles.base.transform==='rotate(3deg)' && getComputedStyle(d.querySelector('[data-quill-editor-selected]')).transform!=='none' && getComputedStyle(d.body).color==='rgb(36, 40, 58)';})()''', theme+' theme reaches floating controls while preserving document styles')
        page.check('''(() => {
            const rgb=value=>value.match(/[0-9.]+/g).slice(0,3).map(Number).map(n=>{n/=255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4});
            const luminance=value=>rgb(value).reduce((sum,n,i)=>sum+n*[.2126,.7152,.0722][i],0);
            const contrast=(a,b)=>{const x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)};
            const probe=document.createElement('span');document.body.append(probe);probe.style.background='var(--editor-bg)';const bg=getComputedStyle(probe).backgroundColor;
            probe.style.color='var(--editor-muted)';const muted=getComputedStyle(probe).color;probe.style.color='var(--editor-ink)';const ink=getComputedStyle(probe).color;probe.remove();return contrast(ink,bg)>=4.5 && contrast(muted,bg)>=4.5;
        })()''', theme+' theme has readable primary and secondary text contrast')
        page.evaluate('document.querySelector("#editor-tab-layout").focus()')
        page.command('Input.dispatchKeyEvent', type='keyDown', key='Tab', code='Tab', windowsVirtualKeyCode=9)
        page.command('Input.dispatchKeyEvent', type='keyUp', key='Tab', code='Tab', windowsVirtualKeyCode=9)
        page.check('getComputedStyle(document.activeElement).outlineStyle==="solid" && getComputedStyle(document.activeElement).outlineWidth==="2px"', theme+' theme keeps keyboard focus visible')
        if screenshot:
            page.evaluate('document.querySelector(".editor-rightbar").scrollTop=0')
            Path(screenshot).with_suffix('.'+theme+'.png').write_bytes(base64.b64decode(page.command('Page.captureScreenshot',format='png')['data']))
        page.evaluate('QuillEditor.ui.actions.open("qa-theme")')
